3	const sha=b=>crypto.createHash('sha256').update(b).digest('hex'),cp=JSON.parse(fs.readFileSync(path.join(here,input))),root=JSON.parse(fs.readFileSync(path.join(here,'project.json'))).project;assert.equal(path.resolve(cp.project),path.resolve(root));
