6	const frozen=new Map();for(const v of Object.values(state.source_versions??{}))frozen.set(v.object_ref,v.sha256);for(const u of state.units)for(const value of [u.draft_review,u.replay_review])if(value?.frozen_ref)frozen.set(value.frozen_ref,value.report_sha256);
7	for(const [ref,expected]of frozen){assert(/^\.writer\/objects\//.test(ref));assert.equal(sha(fs.readFileSync(path.join(root,ref))),expected,ref);}
8	const result={ok:true,at:new Date().toISOString(),label,project:root,checkpoint:input,checkpoint_sha256:sha(fs.readFileSync(path.join(here,input))),revision:state.revision,registered_units:cp.registered_units,state_sha256:sha(bytes),verified_files:checked,frozen_source_and_report_objects_verified:frozen.size,note:'Read-only restoration check before continuing current-book reading/review/export; not literary acceptance.'};
9	fs.writeFileSync(path.join(here,`reading-resume-${label}-verification.json`),JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(result));
